cd /opt/nxeon && node -e "
const fs=require('fs');
const s=fs.readFileSync('worker/migrate-real.ts','utf8');
let d=0,min=0,line=1,minLine=1;
for(let i=0;i<s.length;i++){const c=s[i];if(c==='\n')line++;if(c==='{')d++;if(c==='}'){d--;if(d<min){min=d;minLine=line;}}}
console.log('final brace depth:',d,'min depth:',min,'at line',minLine);
const p=(s.match(/\(/g)||[]).length-(s.match(/\)/g)||[]).length;
console.log('paren delta (naive):',p);
console.log('backticks:',(s.match(/\`/g)||[]).length);
console.log('lines:',s.split('\n').length);
" 2>&1

cd /opt/nxeon && node -e "
const ts=require('typescript');
const fs=require('fs');
for (const f of ['worker/migrate-real.ts','worker/migrate.ts','worker/migrate-detect.ts','lib/actions-migrate.ts','app/dashboard/migrate/page.tsx']) {
  const src=fs.readFileSync(f,'utf8');
  const sf=ts.createSourceFile(f, src, ts.ScriptTarget.ESNext, true, f.endsWith('.tsx')?ts.ScriptKind.TSX:ts.ScriptKind.TS);
  const diags=sf.parseDiagnostics||[];
  console.log(f, 'parseErrors:', diags.length);
  diags.slice(0,10).forEach(d=>{
    const lc=sf.getLineAndCharacterOfPosition(d.start);
    console.log('   line',lc.line+1, ts.flattenDiagnosticMessageText(d.messageText,' '));
  });
}
" 2>&1 | head -60

content.content:
1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import type { Job } from "@prisma/client";
4	import {
5	  runRealMigration,
6	  issueMigrationCertificates,
7	  migrationWorkDir,
8	  type MigrationStepResult,
9	  type ScanSnapshot,
10	} from "./migrate-real";
11	import { resolveCloudflareToken } from "../lib/cloudflare-oauth";
12	
13	/**
14	 * Real cross-provider transfer is OFF by default. It only runs when the operator
15	 * explicitly sets ENABLE_REAL_MIGRATION=1 (and never in the sandbox). Otherwise
16	 * the safe, progress-reporting SIMULATION below runs. The real engine
17	 * (worker/migrate-real.ts) is hardened against shell injection and never lets a
18	 * secret touch a command string. Enable it only after testing on a throwaway VM.
19	 */
20	const REAL_MIGRATION = process.env.ENABLE_REAL_MIGRATION === "1" && !SANDBOX;
21	
22	/**
23	 * MIGRATE — pull a customer's files + databases from another provider's VPS onto
24	 * their new Nxeon server.
25	 *
26	 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
27	 *   MIGRATE: runMigration,
28	 *
29	 * Ownership + validation happen at enqueue time (lib/actions-migrate.ts), so the
30	 * handler trusts `payload.migrationId`.
31	 *
32	 * SAFETY: real cross-provider transfer (SSH into the source, rsync-pull files,
33	 * mysqldump/pg_dump → import on target) is involved infra that has to be built
34	 * out carefully — see the TODO(real migration) block below. For now this runs a
35	 * SANDBOX-SAFE SIMULATION that walks realistic stages and reports progress, so
36	 * it is harmless to run against real infrastructure. It NEVER opens a real SSH
37	 * connection to the customer's source box.
38	 *
39	 * On completion (DONE or FAILED) every stored source secret is CLEARED:
40	 * `sourcePasswordEnc` and each database's `passEnc`. A finished Migration row
41	 * therefore never retains usable credentials.
42	 */
43	
44	type MigratePayload = {
45	  migrationId?: string;
46	  /**
47	   * `"tls"` turns this job into the POST-DNS-CUTOVER certificate pass instead of
48	   * a migration: it re-runs the certificate ladder against the site
49	   * configuration the original run persisted, and copies nothing. See
50	   * `runPostCutoverTls` for why that is a separate phase rather than a separate
51	   * JobType (prisma/schema.prisma is frozen; `MIGRATE` already exists and is
52	   * already registered in worker/index.ts's handler map).
53	   */
54	  phase?: "tls";
55	};
56	type MigrationItems = {
57	  paths?: string[];
58	  // Legacy per-DB list (with encrypted password) — kept optional for old rows.
59	  databases?: { engine: string; name: string; user: string; passEnc?: string }[];
60	  // Passwordless lift-and-shift plan (extended TS shape carried through the
61	  // existing Migration.items Json column — no schema change).
62	  dbEngines?: string[];
63	  dockerVolumes?: string[];
64	  composeDirs?: string[];
65	  verifyPorts?: number[];
66	  hasContainers?: boolean;
67	  webServers?: string[];
68	  runtimes?: string[];
69	  scan?: ScanSnapshot;
70	  // Written back at completion: the honest per-step outcome summary.
71	  results?: MigrationStepResult[];
72	};
73	
74	const MAX_LOG_CHARS = 8000;
75	
76	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
77	
78	/** Append a timestamped line to a log tail, keeping it bounded. */
79	function appendLog(prev: string | null | undefined, line: string): string {
80	  const stamp = new Date().toISOString().slice(11, 19);
81	  const next = `${prev ?? ""}${prev ? "\n" : ""}[${stamp}] ${line}`;
82	  return next.length > MAX_LOG_CHARS ? next.slice(next.length - MAX_LOG_CHARS) : next;
83	}
84	
85	async function loadMigration(job: Job) {
86	  const payload = (job.payload ?? {}) as MigratePayload;
87	  if (!payload.migrationId) throw new Error("migrate job: missing migrationId");
88	  const migration = await db.migration.findUnique({ where: { id: payload.migrationId } });
89	  if (!migration) throw new Error(`Migration ${payload.migrationId} not found`);
90	  // Migration has no Prisma relation to Server (serverId is a plain FK) — resolve
91	  // the target server row separately. `dedicatedIp` is needed by the real engine
92	  // to compute the SSH connection target.
93	  const server = await db.server.findUnique({
94	    where: { id: migration.serverId },
95	    include: { dedicatedIp: true },
96	  });
97	  return { ...migration, server };
98	}
99	
100	/**
101	 * Strip every source secret from a migration row. Called once the job finishes
102	 * (success or failure) so a completed migration never keeps usable credentials.
103	 */
104	async function clearSecrets(
105	  migrationId: string,
106	  items: MigrationItems,
107	  results?: MigrationStepResult[]
108	) {
109	  // Preserve every NON-secret field (so the wizard/summary keep working) while
110	  // stripping the only secret carried in items — each legacy DB's passEnc. The
111	  // source SSH password (sourcePasswordEnc column) is nulled separately.
112	  const scrubbed: MigrationItems = {
113	    ...items,
114	    databases: (items.databases ?? []).map((d) => ({
115	      engine: d.engine,
116	      name: d.name,
117	      user: d.user,
118	      // passEnc dropped entirely
119	    })),
120	    ...(results ? { results } : {}),
121	  };
122	  await db.migration.update({
123	    where: { id: migrationId },
124	    data: { sourcePasswordEnc: null, items: scrubbed as any },
125	  });
126	}
127	
128	async function report(
129	  migrationId: string,
130	  progress: number,
131	  step: string,
132	  logLine: string,
133	  logTail: string | null
134	): Promise<string> {
135	  const log = appendLog(logTail, logLine);
136	  await db.migration.update({
137	    where: { id: migrationId },
138	    data: { status: "RUNNING", progress, step, log },
139	  });
140	  return log;
141	}
142	
143	async function notify(userId: string, title: string, body?: string, href?: string) {
144	  try {
145	    await db.notification.create({ data: { userId, title, body, href } });
146	  } catch (e) {
147	    console.error("[migrate] notify failed", e);
148	  }
149	}
150	
151	// ---- TLS inputs: resolved HERE, on the Nxeon side --------------------------
152	/**
153	 * The three certificate inputs `runRealMigration` / `issueMigrationCertificates`
154	 * declare and that this caller used to drop on the floor.
155	 *
156	 * Real incident: the engine shipped a complete three-rung TLS ladder
157	 * (migrated certificate → DNS-01 wildcard via Cloudflare → HTTP-01 webroot) and
158	 * this call site passed only `{migration, target, items, report}`. The
159	 * consequences were invisible because every rung *degraded politely*:
160	 *
161	 *   - no `cloudflareToken`  ⇒ rung 3 could never fire, so every multi-tenant
162	 *     app was told "Connect Cloudflare in Settings" even when the customer had
163	 *     already completed the OAuth flow. A `*.domain` cert cannot be issued any
164	 *     other way (HTTP-01 cannot validate a wildcard), so those tenants were
165	 *     permanently stuck on a certificate warning.
166	 *   - no `acmeEmail`        ⇒ every certificate registered
167	 *     `--register-unsafely-without-email`, so Let's Encrypt has no address to
168	 *     send the 20/7/1-day expiry warnings to. That failure is silent for 60 days
169	 *     and then takes the site down.
170	 *   - no `knownDomains`     ⇒ hostnames the customer registered WITH US were
171	 *     excluded from the published set and from the certificate SANs.
172	 *
173	 * Everything is read from OUR database — never off the customer's box.
174	 * Resolution never throws: a missing/expired Cloudflare connection simply drops
175	 * the engine to a lower rung, exactly as it does for a customer who never
176	 * connected, and that is reported honestly in the run log.
177	 */
178	type MigrationTlsInputs = {
179	  cloudflareToken: string | null;
180	  acmeEmail: string | null;
181	  knownDomains: string[];
182	  /** One line for the run log, so the customer can see which rungs are available. */
183	  note: string;
184	};
185	
186	async function resolveTlsInputs(userId: string): Promise<MigrationTlsInputs> {
187	  let cloudflareToken: string | null = null;
188	  let acmeEmail: string | null = null;
189	  const knownDomains: string[] = [];
190	  const notes: string[] = [];
191	
192	  try {
193	    const user = await db.user.findUnique({
194	      where: { id: userId },
195	      select: { id: true, email: true, cloudflareTokenEnc: true },
196	    });
197	    if (user) {
198	      // The account email is the ACME contact. This is what turns Let's
199	      // Encrypt's expiry warnings back on; without it a certificate that stops
200	      // renewing is only discovered by a visitor.
201	      acmeEmail = user.email ?? null;
202	      const resolved = await resolveCloudflareToken(user);
203	      if (resolved.token) {
204	        cloudflareToken = resolved.token;
205	        notes.push("your connected Cloudflare account is available, so wildcard certificates can be issued automatically (DNS-01)");
206	      } else {
207	        notes.push(
208	          "Cloudflare is not connected, so a wildcard certificate (needed when an app gives each tenant its own subdomain) cannot be issued automatically — connect it in Settings and we can finish that for you"
209	        );
210	      }
211	    }
212	  } catch (e) {
213	    // A DB hiccup here must never fail a migration — it only costs a rung.
214	    console.error("[migrate] could not resolve Cloudflare/ACME inputs", e);
215	    notes.push("we could not read your Cloudflare connection just now, so certificates were issued without it");
216	  }
217	
218	  try {
219	    const domains = await db.domain.findMany({
220	      where: { userId },
221	      select: { name: true },
222	      orderBy: { name: "asc" },
223	      take: 50,
224	    });
225	    for (const d of domains) if (d.name) knownDomains.push(d.name);
226	  } catch (e) {
227	    console.error("[migrate] could not load registered domains", e);
228	  }
229	
230	  return { cloudflareToken, acmeEmail, knownDomains, note: notes.join("; ") };
231	}
232	
233	/**
234	 * POST-DNS-CUTOVER certificate pass.
235	 *
236	 * HTTP-01 cannot validate a hostname that still resolves to the OLD server —
237	 * that is a property of the protocol, not a bug — so at migration time every
238	 * name whose DNS has not moved comes back as a named pending item. This is the
239	 * second half: run the same ladder again once the record is live.
240	 *
241	 * `issueMigrationCertificates` was written for exactly this and, until now, had
242	 * ZERO callers, so TLS was never retried after cutover and the customer's first
243	 * HTTPS visit was a certificate warning.
244	 *
245	 * Deliberate properties:
246	 *   - It copies NOTHING. It re-reads the `sites.json` the original run persisted
247	 *     on the target, walks the ladder, and reloads the vhost. A migration is
248	 *     never re-run by this path, so an accidental/duplicate enqueue cannot
249	 *     re-transfer a customer's data over the top of itself.
250	 *   - It is idempotent: certbot's `--keep-until-expiring` makes it a no-op once
251	 *     a certificate is in place, so it is safe to enqueue repeatedly.
252	 *   - It does NOT touch `Migration.status`. The terminal outcome belongs to the
253	 *     run that measured it; a certificate pass has not re-probed the sites and
254	 *     must not silently upgrade `COMPLETED_WITH_ISSUES` to `DONE`.
255	 *   - It never touches the SOURCE server.
256	 *
257	 * Enqueue it with:
258	 *   db.job.create({ data: { type: "MIGRATE", payload: { migrationId, phase: "tls" } } })
259	 */
260	async function runPostCutoverTls(
261	  migration: Awaited<ReturnType<typeof loadMigration>>,
262	  items: MigrationItems
263	): Promise<void> {
264	  const target = migration.server;
265	  const targetName = target ? target.label || target.hostname : "your server";
266	
267	  // Append-only log write: the migration row is already terminal and its status,
268	  // progress and step are the honest record of the run that produced them.
269	  let log = migration.log ?? null;
270	  const say = async (line: string) => {
271	    log = appendLog(log, line);
272	    await db.migration.update({ where: { id: migration.id }, data: { log } }).catch(() => {});
273	  };
274	
275	  if (!REAL_MIGRATION) {
276	    await say("HTTPS re-check skipped: real migration is not enabled on this platform, so no certificate was requested.");
277	    return;
278	  }
279	
280	  await say("Your DNS has moved — re-checking HTTPS and issuing any certificate that could not be issued before.");
281	  const tls = await resolveTlsInputs(migration.userId);
282	  if (tls.note) await say(`  ${tls.note}.`);
283	
284	  const res = await issueMigrationCertificates({
285	    target: target as any,
286	    migrationId: migration.id,
287	    extraDomains: tls.knownDomains,
288	    cloudflareToken: tls.cloudflareToken,
289	    acmeEmail: tls.acmeEmail,
290	    // Progress is meaningless for a post-cutover pass (the migration is over), so
291	    // the reporter is used purely as a log sink.
292	    report: async (_p, _s, line) => {
293	      await say(line);
294	    },
295	  });
296	
297	  if (res.error) {
298	    await say(`HTTPS re-check could not run: ${res.error}`);
299	    await notify(
300	      migration.userId,
301	      `Couldn't finish HTTPS on ${targetName}`,
302	      `${res.error} Your site keeps serving; only the certificate step is outstanding. Nothing on your old server was touched.`,
303	      "/dashboard/migrate"
304	    );
305	    return;
306	  }
307	
308	  const secured = res.secured ?? [];
309	  const pending = res.pending ?? [];
310	  if (secured.length) {
311	    await say(`HTTPS is live for ${secured.slice(0, 8).join(", ")}${secured.length > 8 ? ` (+${secured.length - 8} more)` : ""}.`);
312	  }
313	  for (const p of pending.slice(0, 8)) await say(`  HTTPS still outstanding for ${p.domain}: ${p.why}. To finish: ${p.fix}`);
314	
315	  await notify(
316	    migration.userId,
317	    pending.length
318	      ? `HTTPS on ${targetName} — ${secured.length} secured, ${pending.length} still to finish`
319	      : `HTTPS is live on ${targetName}`,
320	    (secured.length ? `A valid certificate is now in place for ${secured.slice(0, 6).join(", ")}. ` : "") +
321	      (pending.length
322	        ? `Still outstanding: ${pending.slice(0, 4).map((p) => `${p.domain} — ${p.why}`).join(" | ")}. `
323	        : "") +
324	      // Said every time, because it is the customer's actual safety net and the
325	      // moment DNS has just moved is the moment they most need to know it.
326	      "Your old server was only ever read from — nothing on it was changed, so pointing DNS back to it is still a complete rollback.",
327	    "/dashboard/migrate"
328	  );
329	}
330	
331	export async function runMigration(job: Job): Promise<void> {
332	  const migration = await loadMigration(job);
333	  const items = (migration.items ?? {}) as MigrationItems;
334	  const paths = items.paths ?? [];
335	  const target = migration.server;
336	  const targetName = target ? target.label || target.hostname : "your server";
337	
338	  // The post-cutover certificate pass shares this handler (and therefore the
339	  // already-registered MIGRATE JobType) but is NOT a migration: it copies
340	  // nothing and must never fall through into the transfer below.
341	  if (((job.payload ?? {}) as MigratePayload).phase === "tls") {
342	    try {
343	      await runPostCutoverTls(migration, items);
344	    } catch (e) {
345	      console.error(`[migrate] post-cutover TLS for ${migration.id} failed:`, e);
346	      // Swallowed on purpose: a failed certificate retry must not mark the
347	      // customer's finished migration as failed, and must not make the job loop
348	      // retry a phase that will keep failing for the same reason.
349	    }
350	    return;
351	  }
352	
353	  // Fresh start (also lets a retried job re-enter cleanly).
354	  let log = appendLog(null, `Starting migration from ${migration.sourceUser}@${migration.sourceHost}:${migration.sourcePort} → ${targetName}`);
355	  await db.migration.update({
356	    where: { id: migration.id },
357	    data: { status: "RUNNING", progress: 5, step: "Starting", log, lastError: null, finishedAt: null },
358	  });
359	
360	  // Shared progress reporter: threads the bounded log tail through each update so
361	  // both the real engine and the simulation write to the same Migration row.
362	  const reportStep = async (progress: number, step: string, line: string) => {
363	    log = await report(migration.id, progress, step, line, log);
364	  };
365	
366	  try {
367	    if (REAL_MIGRATION) {
368	      // ---- REAL lift-and-shift (hardened; opt-in via ENABLE_REAL_MIGRATION) --
369	      // Resolve the TLS inputs BEFORE the engine starts. These three arguments
370	      // are what make the certificate ladder reachable at all — see
371	      // resolveTlsInputs for the failure each dropped argument caused.
372	      const tls = await resolveTlsInputs(migration.userId);
373	      if (tls.note) await reportStep(5, "Starting", `HTTPS: ${tls.note}.`);
374	
375	      const summary = await runRealMigration({
376	        migration: {
377	          id: migration.id,
378	          sourceHost: migration.sourceHost,
379	          sourcePort: migration.sourcePort,
380	          sourceUser: migration.sourceUser,
381	          sourcePasswordEnc: migration.sourcePasswordEnc,
382	        },
383	        target: target as any,
384	        items,
385	        report: reportStep,
386	        // Rung 3 of the certificate ladder: a wildcard (`*.domain`) can ONLY be
387	        // issued with a DNS-01 challenge, so a multi-tenant app is stuck on a
388	        // certificate warning without this token.
389	        cloudflareToken: tls.cloudflareToken,
390	        // Without this every cert is `--register-unsafely-without-email` and
391	        // Let's Encrypt has nobody to warn before it expires.
392	        acmeEmail: tls.acmeEmail,
393	        // Hostnames the customer registered with us, folded into the published
394	        // set and the certificate SANs when they belong to a served site.
395	        knownDomains: tls.knownDomains,
396	      });
397	
398	      // The engine returns an HONEST outcome. A run that executed every step but
399	      // left a source domain dark — or a migrated unit crash-looping — is NOT a
400	      // success, and must never be written back as one.
401	      //
402	      // This line is why the 2026-07-25 migration reported "Completed" while the
403	      // customer's site served a certificate warning and then Apache's default
404	      // page: the status was hardcoded, so no amount of verification downstream
405	      // could change what the customer was told. `COMPLETED_WITH_ISSUES` is
406	      // terminal (MigrationWizard treats it as an end state) but visibly distinct.
407	      const clean = summary.outcome === "COMPLETED";
408	      const unserved = summary.unservedDomains ?? [];
409	      await db.migration.update({
410	        where: { id: migration.id },
411	        data: {
412	          status: clean ? "DONE" : "COMPLETED_WITH_ISSUES",
413	          progress: 100,
414	          step: clean ? "Completed" : "Finished — some sites need attention",
415	          finishedAt: new Date(),
416	        },
417	      });
418	      // Persist the honest step-by-step summary (secret-free) into items.results.
419	      await clearSecrets(migration.id, items, summary.results);
420	
421	      const workDir = migrationWorkDir(migration.id);
422	      const running = summary.verifiedRunning.length;
423	      const manual = summary.needsAttention.length;
424	      const tail =
425	        `Any DB dumps that couldn't import were kept under ${workDir}/dumps. ` +
426	        `Your old server is untouched — if anything looks wrong, point DNS back to it while we sort this out.`;
427	      // Lead with the bad news when there is bad news. Burying dark domains under
428	      // a "completed" headline is what cost the customer a working site.
429	      const body = clean
430	        ? `Lift-and-shift onto ${targetName} finished. ${running} item(s) migrated & verified running; ` +
431	          `${manual} copied that may need a manual step. ` +
432	          (manual ? `To finish: ${summary.needsAttention.slice(0, 5).join(" | ")}${manual > 5 ? " …" : ""}. ` : "") +
433	          tail
434	        : `Lift-and-shift onto ${targetName} finished, but it is NOT fully live yet. ` +
435	          (unserved.length
436	            ? `These site(s) are not serving on the new server: ${unserved.slice(0, 8).join(", ")}${unserved.length > 8 ? ` (+${unserved.length - 8} more)` : ""}. `
437	            : "") +
438	          `${(summary.outcomeReasons ?? []).join("; ")}. ` +
439	          `${running} item(s) verified running. ` +
440	          tail;
441	      await notify(
442	        migration.userId,
443	        clean
444	          ? `Migration to ${targetName} completed`
445	          : `Migration to ${targetName} finished — ${unserved.length || "some"} site(s) need attention`,
446	        body,
447	        "/dashboard/migrate"
448	      );
449	      return;
450	    }
451	
452	    // ---- Progress-reporting SIMULATION of the lift-and-shift (default) --------
453	    // Mirrors the real engine's flow (dump DBs via root, install prerequisites,
454	    // import DBs, compose up, verify) with SYNTHETIC success. Delays are short so
455	    // the UI polls a live-feeling progression. NEVER opens a real SSH connection.
456	    const dbEngines = (items.dbEngines ?? []).filter((e) => e === "mysql" || e === "postgres");
457	    const composeDirs = items.composeDirs ?? [];
458	    const webServers = items.webServers ?? [];
459	    const runtimes = items.runtimes ?? [];
460	    const verifyPorts = items.verifyPorts ?? [];
461	    const hasContainers = !!items.hasContainers || composeDirs.length > 0;
462	    const simResults: MigrationStepResult[] = [];
463	
464	    await reportStep(6, "Connecting…", `Connecting to your Nxeon server (${targetName}) to prepare the lift-and-shift.`);
465	    await sleep(SANDBOX ? 500 : 1000);
466	    await reportStep(12, "Connecting to source…", `Connecting to ${migration.sourceHost} over SSH (port ${migration.sourcePort}). Authenticated with root.`);
467	    await sleep(SANDBOX ? 400 : 800);
468	
469	    // Prerequisites stage.
470	    const prereqLabels: string[] = [];
471	    if (dbEngines.includes("mysql")) prereqLabels.push("MySQL/MariaDB server");
472	    if (dbEngines.includes("postgres")) prereqLabels.push("PostgreSQL server");
473	    if (hasContainers) prereqLabels.push("Docker Engine + compose");
474	    for (const w of webServers) prereqLabels.push(w === "nginx" ? "nginx" : "Apache");
475	    for (const rt of runtimes) prereqLabels.push(rt === "nodejs" ? "Node.js" : "Python 3 + pip");
476	    if (prereqLabels.length) {
477	      await reportStep(18, "Installing prerequisites…", `Installing on ${targetName}: ${prereqLabels.join(", ")}.`);
478	      for (const lbl of prereqLabels) {
479	        await sleep(SANDBOX ? 200 : 400);
480	        await reportStep(20, "Installing prerequisites…", `  ${lbl}: installed.`);
