2430	/**
2431	 * Decide the terminal outcome of a run. Extracted from `runRealMigration` so it
2432	 * is testable in isolation — see MigrationScoreInput.
2433	 *
2434	 * The invariant that matters, and the one the 2026-07-25 run violated: this
2435	 * function can return COMPLETED **only** when every hostname the old server
2436	 * answered on serves here and every migrated unit is healthy. A denominator we
2437	 * get to pick is not a measurement, so `sourceDomains` (read off the source)
2438	 * wins over `probeNames` (chosen by us), and falling back to `probeNames` is
2439	 * itself an outcome reason.
2440	 */
2441	export function judgeMigrationOutcome(input: MigrationScoreInput): MigrationScore {
2442	  const servingSet = new Set(input.siteProbes.filter((p) => p.serving).map((p) => p.domain));
2443	  const probedSet = new Set(input.probeNames);
2444	  const scoredAgainst = input.sourceDomains.length ? input.sourceDomains : input.probeNames;
2445	
2446	  // Everything the old server served that this one does not. A name we did not
2447	  // get to probe counts here too — "we did not check" is not "it works" — but it
2448	  // is worded separately so the customer is never told a site is broken when
2449	  // what we actually mean is that we ran out of probe budget.
2450	  const unservedDomains = scoredAgainst.filter((d) => !servingSet.has(d));
2451	  const failedProbe = unservedDomains.filter((d) => probedSet.has(d));
2452	  const uncheckedDomains = unservedDomains.filter((d) => !probedSet.has(d));
2453	
2454	  // Anything on this list means the customer's move is NOT finished, however
2455	  // many individual steps succeeded.
2456	  const outcomeReasons: string[] = [];
2457	  if (failedProbe.length) {
2458	    outcomeReasons.push(
2459	      `${failedProbe.length} of the ${scoredAgainst.length} domain(s) the old server answered on ${failedProbe.length === 1 ? "does" : "do"} not serve here: ${failedProbe.slice(0, 8).join(", ")}${failedProbe.length > 8 ? " …" : ""}`
2460	    );
2461	  }
2462	  if (uncheckedDomains.length) {
2463	    outcomeReasons.push(
2464	      `${uncheckedDomains.length} domain(s) the old server answered on were not checked at all: ${uncheckedDomains.slice(0, 6).join(", ")}${uncheckedDomains.length > 6 ? " …" : ""}`
2465	    );
2466	  }
2467	  if (input.unitBlockers.length) {
2468	    outcomeReasons.push(
2469	      `${input.unitBlockers.length} migrated service(s) are not running: ${input.unitBlockers.slice(0, 5).map((b) => b.domain).join(", ")}${input.unitBlockers.length > 5 ? " …" : ""}`
2470	    );
2471	  }
2472	  const failedSteps = input.failedSteps ?? [];
2473	  if (failedSteps.length) {
2474	    outcomeReasons.push(
2475	      `${failedSteps.length} step(s) failed: ${failedSteps.slice(0, 5).map((s) => s.step).join(", ")}${failedSteps.length > 5 ? " …" : ""}`
2476	    );
2477	  }
2478	  const unreadContainers = input.unreadContainers ?? 0;
2479	  if (unreadContainers > 0) {
2480	    outcomeReasons.push(
2481	      `${unreadContainers} container(s) on the old server could not be read, so they were not recreated here — start them by hand`
2482	    );
2483	  }
2484	  if (!input.sourceDomains.length && input.probeNames.length) {
2485	    outcomeReasons.push(
2486	      "the old server's live configuration could not be read, so this score is measured against the sites we published rather than against everything the old server served — check the rest by hand"
2487	    );
2488	  }
2489	
2490	  return {
2491	    scoredAgainst,
2492	    servingCount: scoredAgainst.filter((d) => servingSet.has(d)).length,
2493	    unservedDomains,
2494	    failedProbe,
2495	    uncheckedDomains,
2496	    outcome: outcomeReasons.length ? "COMPLETED_WITH_ISSUES" : "COMPLETED",
2497	    outcomeReasons,
2498	  };
2499	}

