671	/**
672	 * Idempotently ensure each allowlisted package is present on the target. Runs
673	 * `apt-get update` once, then for each key: skip if the check passes, else try
674	 * apt → dnf → yum with the FIXED package string. Returns which were newly
675	 * installed / already present / failed. Never throws (best-effort per package).
676	 *
677	 * `say` is optional so every existing call site keeps working unchanged; when it
678	 * is supplied the slow parts (metadata refresh + each install) narrate
679	 * themselves, because a package install is one of the three steps that can sit
680	 * silent for minutes (see withHeartbeat).
681	 */
682	async function ensurePackages(
683	  conn: Client,
684	  keys: PkgKey[],
685	  say?: (line: string) => Promise<void>
686	): Promise<{ key: PkgKey; ok: boolean; already: boolean; err?: string }[]> {
687	  const beat = <T,>(what: string, run: () => Promise<T>): Promise<T> =>
688	    say ? withHeartbeat(what, say, run) : run();
689	  const out: { key: PkgKey; ok: boolean; already: boolean; err?: string }[] = [];
690	  if (keys.length === 0) return out;
691	  // `DEBIAN_FRONTEND=noninteractive` is NOT sufficient on Ubuntu 22.04+.
692	  // `needrestart` hooks dpkg's post-install phase and opens an interactive
693	  // "which services should be restarted?" prompt on a tty nobody is reading,
694	  // which wedges apt until INSTALL_TIMEOUT_MS expires.
695	  //
696	  // Seen live on a real migration (2026-07-25): installing certbot blocked on
697	  // /usr/lib/needrestart/dpkg-status for the FULL 10-minute timeout, which was
698	  // the entire HTTPS window — the run finished with soulpilates.com.vn and
699	  // srv1182755.hstgr.cloud still on plain HTTP. A hang here does not just cost
700	  // time, it silently costs certificates.
701	  //
702	  // NEEDRESTART_MODE=a answers that prompt automatically (restart what's needed);
703	  // NEEDRESTART_SUSPEND=1 disables the hook outright on versions that honour it.
704	  // The force-conf* options settle the OTHER classic apt prompt — "a config file
705	  // you modified has changed" — by keeping the existing file, which is the right
706	  // answer on a machine we are migrating INTO.
707	  const APT_ENV = "DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a NEEDRESTART_SUSPEND=1";
708	  const APT_OPTS = `-o Dpkg::Options::="--force-confdef" -o Dpkg::Options::="--force-confold"`;
709	  // Refresh apt metadata once (best-effort; ignored on non-apt systems). Also
710	  // finish any dpkg run a previous interrupted install left half-configured —
711	  // otherwise every later apt call inherits the wedge.
712	  await beat("finishing any half-configured package install", () =>
713	    execRemote(conn, `${APT_ENV} dpkg --configure -a >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => ({ code: 0, stdout: "", stderr: "" }))
714	  );
715	  await beat("refreshing the package index (apt-get update)", () =>
716	    execRemote(conn, `${APT_ENV} apt-get update -y >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => ({ code: 0, stdout: "", stderr: "" }))
717	  );
718	  for (const key of keys) {
719	    const already = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((r) => r.code === 0).catch(() => false);
720	    if (already) {
721	      out.push({ key, ok: true, already: true });
722	      continue;
723	    }
724	    // Docker is special-cased: install via the OFFICIAL convenience script — the
725	    // SAME method the platform's own provisioning uses (buildCloudInit in
726	    // worker/index.ts). The apt/dnf package list fails on Ubuntu because
727	    // `docker-compose-plugin` isn't in Ubuntu's default apt repo, so the whole
728	    // install returned non-zero and Docker never came up. get.docker.com adds
729	    // Docker's own repo and installs docker-ce + the compose plugin across
730	    // Debian/Ubuntu/RHEL. The command is a FIXED constant (no source input);
731	    // still best-effort + logged like every other package.
732	    const install =
733	      key === "docker"
734	        ? `curl -fsSL https://get.docker.com | sh && systemctl enable --now docker`
735	        : `${APT_ENV} apt-get install -y ${APT_OPTS} ${PKG_APT[key]} ` +
736	          `|| dnf install -y ${PKG_DNF[key]} ` +
737	          `|| yum install -y ${PKG_DNF[key]}`;
738	    const r = await beat(`installing ${PKG_LABEL[key]}`, () =>
739	      execRemote(conn, install, INSTALL_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }))
740	    );
741	    const nowPresent = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
742	    if (nowPresent) {
743	      out.push({ key, ok: true, already: false });
744	    } else {
745	      const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
746	      out.push({ key, ok: false, already: false, err: tail || `install exit ${r.code}` });
747	    }
748	  }
749	  return out;
750	}
