3102	/**
3103	 * Parse the stale-reference sweep's tab-delimited output.
3104	 *
3105	 * TWO defects from the 2026-07-26 rehearsal live here, and the second is the
3106	 * reason this is a named, tested function instead of an inline loop:
3107	 *
3108	 *  1. It read `clean(out.stdout).split("\n")`, and `clean` deletes tabs. The very
3109	 *     next statement was `raw.indexOf("\t") < 0 → continue`, so EVERY line was
3110	 *     skipped, 100% of the time, on every run this code has ever had.
3111	 *  2. The caller then reported "nothing in the copied files still points at the
3112	 *     old server" — status `running`, a clean bill of health — produced by
3113	 *     parsing zero lines. This is the detection for field note 11 ("a frontend
3114	 *     calling the old server's API is a silent failure"), and it was answering
3115	 *     the question without ever having looked.
3116	 *
3117	 * `SWEEP_OK` was already being printed by the script and had never been read.
3118	 * It is now the difference between "we looked and it is clean" and "we could not
3119	 * look" — the caller must not claim the former without `ok`.
3120	 */
3121	export function parseStaleSweep(stdout: string, maxHits = SWEEP_MAX_HITS): StaleSweepResult {
3122	  const hits: StaleHit[] = [];
3123	  const certRefs = new Map<string, string>();
3124	  const seenHit = new Set<string>();
3125	  let ok = false;
3126	  // cleanRows, NOT clean().split(): `clean` strips the tab this parse is keyed on.
3127	  for (const raw of cleanRows(stdout, 60000)) {
3128	    const tab = raw.indexOf("\t");
3129	    if (tab < 0) continue;
3130	    const kind = raw.slice(0, tab);
3131	    const rest = raw.slice(tab + 1);
3132	    if (kind === "SWEEP_OK") {
3133	      ok = true;
3134	      continue;
3135	    }
3136	    const hit = parseSweepHit(rest);
3137	    if (!hit) continue;
3138	    if (kind === "HIT") {
3139	      const key = `${hit.file}|${hit.value}`;
3140	      if (seenHit.has(key) || hits.length >= maxHits) continue;
3141	      seenHit.add(key);
3142	      hits.push(hit);
3143	    } else if (kind === "CERTREF") {
3144	      const name = normalizeDomain(hit.value.slice(hit.value.lastIndexOf("/") + 1));
3145	      if (name && !certRefs.has(name)) certRefs.set(name, hit.file);
3146	    }
3147	  }
3148	  return { hits, certRefs, ok };
